"""truth — what a perfect learner could recover from a two-slice table generated by the expert DAG (Arm A).

A two-slice table hides the trait (and, in stress settings, measured nodes), so the observed variables follow a
maximal ancestral graph (MAG), and with the tiers the best any learner can do is its tiered PAG. `build()` takes both
from the two-slice DAG with the latent trait and sets aside the pairs that only the hidden earlier years connect.
MAG and PAG are derived from a generating DAG (expert.dynamic_dag) without a search:

1. MAG skeleton: two observed nodes are adjacent iff no observed set d-separates them; when a separating set exists,
   the observed ancestors of the pair are one (Richardson & Spirtes 2002, ancestral-set separation), so one
   d-separation query per pair decides it.
2. MAG marks: a tail at a iff a is an ancestor of b (no selection variables).
3. PAG: causal-learn's FCI orientation rules (R0-R10, with the knowledge semantics of knowledge.py) applied to the
   MAG skeleton with the ancestral separating sets, i.e. FCI with a d-separation oracle minus its adjacency search.
   tests/test_truth.py checks this against brute-force FCI with causal-learn's d-separation oracle.
"""
import contextlib
import io
import itertools
import json
from dataclasses import dataclass, field

import networkx as nx
import numpy as np

from . import expert as E
from . import knowledge as K
from .graphs import MarkGraph


def mag_skeleton(dag: nx.DiGraph, observed):
    """Adjacencies of the MAG over `observed` and a separating set for every non-adjacent pair."""
    O = set(observed)
    anc = {n: nx.ancestors(dag, n) for n in observed}
    adj, sep = [], {}
    for a, b in itertools.combinations(observed, 2):
        Z = ((anc[a] | anc[b]) & O) - {a, b}
        if nx.is_d_separator(dag, {a}, {b}, Z):
            sep[(a, b)] = sep[(b, a)] = Z
        else:
            adj.append((a, b))
    return adj, sep, anc


def oracle(dag: nx.DiGraph, observed, tiers, context=(), exogenous=()):
    """(MAG, PAG) MarkGraphs over `observed`; the PAG uses the tiers and root-node semantics the learners receive."""
    from causallearn.graph.GeneralGraph import GeneralGraph
    from causallearn.graph.Endpoint import Endpoint
    from causallearn.graph.Edge import Edge
    from causallearn.search.ConstraintBased import FCI as F
    from causallearn.utils.cit import CIT

    adj, sep, anc = mag_skeleton(dag, observed)
    mag = MarkGraph(observed, "MAG")
    for a, b in adj:
        mag.add(a, b, "T" if a in anc[b] else "A", "T" if b in anc[a] else "A")

    K.install(context, exogenous)
    idx = {n: i for i, n in enumerate(observed)}
    bk, nodes = K.background(observed, tiers, context, exogenous)
    for n in observed:
        nodes[n].add_attribute("id", idx[n])
    node_list = [nodes[n] for n in observed]
    G = GeneralGraph(node_list)
    for a, b in adj:
        G.add_edge(Edge(nodes[a], nodes[b], Endpoint.CIRCLE, Endpoint.CIRCLE))
    sep_idx = {(idx[a], idx[b]): {idx[z] for z in Z} for (a, b), Z in sep.items()}
    latent = [n for n in dag.nodes if n not in idx]
    gi = nx.relabel_nodes(dag, {n: i for i, n in enumerate(list(observed) + latent)})
    data = np.zeros((10, len(observed)))
    test = CIT(data, "d_separation", true_dag=gi)            # only R4 (discriminating paths) queries it
    with contextlib.redirect_stdout(io.StringIO()):
        F.rule0(G, node_list, sep_idx, bk, False)
        change, first = True, True
        while change:                                        # the loop of causallearn FCI.fci after its search
            change = False
            change = F.rulesR1R2cycle(G, bk, change, False)
            change = F.ruleR3(G, sep_idx, bk, change, False)
            if change or (first and len(bk.forbidden_rules_specs) > 0 and len(bk.required_rules_specs) > 0
                          and len(bk.tier_map.keys()) > 0):
                change = F.ruleR4B(G, -1, data, test, 0.05, sep_idx, change, bk, False)
                first = False
            change = F.ruleR5(G, change, False)
            change = F.ruleR6(G, change, False)
            change = F.ruleR7(G, change, False)
            change = F.rule8(G, node_list, change)
            change = F.rule9(G, node_list, change)
            change = F.rule10(G, change)
    from .graphs import from_causallearn
    pag = from_causallearn(G, list(observed), "PAG")
    return mag, pag


# ---------------------------------------------------------------------------- the truth object of one scenario
@dataclass
class Truth:
    """Everything the metrics need for one scenario (generator edge set x hidden nodes)."""
    name: str
    observed: list
    dag: nx.DiGraph                 # the full generating DAG (latents included)
    mag: MarkGraph
    pag: MarkGraph
    eval_pairs: set                 # frozensets scored by the primary metrics (PROTOCOL.md §6.4)
    key_nodes: list
    summary_pairs: list             # expert edges as (pair, kind) in year t+1
    history_pairs: set = field(default_factory=set)    # adjacent only through the hidden earlier years (unscored)
    excluded_pairs: set = field(default_factory=set)   # near-zero edges, filled per generator (recoverable truth)

    def to_json(self):
        srt = lambda s: sorted(sorted(p) for p in s)
        return dict(name=self.name, observed=self.observed, dag=[list(e) for e in self.dag.edges],
                    mag=self.mag.to_json(), pag=self.pag.to_json(), eval_pairs=srt(self.eval_pairs),
                    key_nodes=self.key_nodes, summary_pairs=[[list(p), k] for p, k in self.summary_pairs],
                    history_pairs=srt(self.history_pairs), excluded_pairs=srt(self.excluded_pairs))

    @classmethod
    def from_json(cls, d):
        dag = nx.DiGraph()
        dag.add_edges_from(d["dag"])
        dag.add_nodes_from(d["observed"])
        fs = lambda xs: {frozenset(p) for p in xs}
        return cls(name=d["name"], observed=d["observed"], dag=dag, mag=MarkGraph.from_json(d["mag"]),
                   pag=MarkGraph.from_json(d["pag"]), eval_pairs=fs(d["eval_pairs"]), key_nodes=d["key_nodes"],
                   summary_pairs=[(tuple(p), k) for p, k in d["summary_pairs"]], history_pairs=fs(d["history_pairs"]),
                   excluded_pairs=fs(d["excluded_pairs"]))

    def scored(self):
        """The pairs the primary metrics score: evaluation pairs minus near-zero (unrecoverable) edges."""
        return self.eval_pairs - self.excluded_pairs


KEY_NODES = ["ldopa_1", "adl_1", "dysk_1", "fluct_1", "se_1"]   # the decision and the outcomes of the escalation question


def evaluation_pairs(observed, context=E.CONTEXT):
    """Primary scoring set: pairs with at least one year-t+1 node and no context node. Pairs inside year t (and of
    baseline nodes with year t) are confounded by the hidden earlier years; context pairs are nuisance structure of
    the pooled design. Both are reported as secondary metrics."""
    ctx = set(context)
    return {frozenset((a, b)) for a, b in itertools.combinations(observed, 2)
            if (E.slice_of(a) == 1 or E.slice_of(b) == 1) and a not in ctx and b not in ctx}


def build(spec: E.ExpertSpec, name: str, context_edges=(), hidden=()) -> Truth:
    """The scenario's truth (PROTOCOL.md §6.4).

    - Adjacencies and marks: the MAG and tiered PAG of the two-slice DAG with the latent trait (no earlier years),
      the structure the expert DAG states.
    - Scored pairs: the evaluation pairs minus those that the hidden earlier years make adjacent (MAG of the DAG with
      one latent earlier year; more years add nothing for v5.1). Those dependences are real in the generated data
      but run through chains of coefficients and are not expert edges, so they are neither rewarded nor penalised.
    - `dag`: the generating structure with one latent earlier year, used by SID's adjustment checks.
    Per-node person effects (a stress setting) make almost every pair adjacent (755 of 903 for v5.1 with history), so
    that setting is scored on the same pairs and reads as 'how many weak, non-expert dependences a method picks up'."""
    dag0 = E.dynamic_dag(spec, L=0, person_effects=False, context_edges=context_edges)
    dag1 = E.dynamic_dag(spec, L=1, person_effects=False, context_edges=context_edges)
    obs = E.observed(spec, hidden=hidden)
    tiers = E.tiers(spec, hidden=hidden)
    mag, pag = oracle(dag0, obs, tiers, E.CONTEXT, E.EXOGENOUS)
    adj1, _, _ = mag_skeleton(dag1, obs)
    history = {frozenset(p) for p in adj1} - mag.adjacencies()
    key = [k for k in KEY_NODES if k in obs]
    summ = [(p, k) for p, k in E.summary_pairs(spec, context_edges) if p[0] in obs and p[1] in obs]
    return Truth(name=name, observed=obs, dag=dag1, mag=mag, pag=pag, eval_pairs=evaluation_pairs(obs) - history,
                 key_nodes=key, summary_pairs=summ, history_pairs=history)


def save(truth: Truth, path):
    path.write_text(json.dumps(truth.to_json()))


def load(path) -> Truth:
    return Truth.from_json(json.loads(path.read_text()))
